UPDATE public.cities SET connectivity_warning = 'The island-wide average hides big variation: villa and homestay speeds rarely match it, and outages are common in the wet season. Test the connection at the specific property, and keep a coworking desk or 4G backup.' WHERE id = 'bali-id';
